import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Gemini 时间特效触发词：升格 / 延时 / 定格","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-time-effects.md","filePath":"tools/gemini-time-effects.md","lastUpdated":1787714366000}'),s={name:"tools/gemini-time-effects.md"};function d(l,e,n,r,p,c){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="gemini-时间特效触发词-升格-延时-定格" tabindex="-1">Gemini 时间特效触发词：升格 / 延时 / 定格 <a class="header-anchor" href="#gemini-时间特效触发词-升格-延时-定格" aria-label="Permalink to &quot;Gemini 时间特效触发词：升格 / 延时 / 定格&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源</p><ul><li>来源：Gemini Web（Google Gemini）现场问答</li><li>时间：2026-08-15</li><li>说明：本文为用户向 Gemini Web 提问拿到的回答，仅做排版整理，文字未做改写。内容由 Gemini 生成，未经官方文档逐一核实；涉及具体机型与帧率参数（Phantom Flex4K、1000fps 等）请以官方文档为准。</li></ul></div><blockquote><p>提问：升格慢动作、延时摄影、突然停格，分别用什么词触发最稳定？</p></blockquote><h2 id="_1-升格慢动作-ultra-slow-motion-high-speed" tabindex="-1">1. 升格慢动作（Ultra Slow-Motion / High-Speed） <a class="header-anchor" href="#_1-升格慢动作-ultra-slow-motion-high-speed" aria-label="Permalink to &quot;1. 升格慢动作（Ultra Slow-Motion / High-Speed）&quot;">​</a></h2><p>单纯使用 <code>slow motion</code> 往往只能得到动作放缓的普通视频，缺乏升格摄影特有的微观物理张力。最稳定的方式是指定工业级高速摄影机型号与极高帧率数值（1000fps），并绑定微观悬浮物理特征。</p><p>最稳触发词组：</p><ul><li><code>shot on Phantom Flex4K at 1000fps ultra slow-motion</code>（锁定千帧高速摄影机质感）</li><li><code>extreme temporal expansion, micro-second physics</code>（时间微秒级膨胀）</li><li><code>suspended in mid-air, capturing fine surface ripples</code>（指定粒子 / 液滴的空气悬浮态）</li></ul><p>标准 Prompt 句式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Captured on Phantom high-speed camera at 1000fps ultra slow-motion: the [Subject/Impact] occurs with extreme temporal expansion, fine droplets and micro-particles suspended crisply in mid-air, subtle surface ripples spreading in slow motion, pristine studio lighting.</span></span></code></pre></div><h2 id="_2-延时摄影-time-lapse-hyperlapse" tabindex="-1">2. 延时摄影（Time-Lapse / Hyperlapse） <a class="header-anchor" href="#_2-延时摄影-time-lapse-hyperlapse" aria-label="Permalink to &quot;2. 延时摄影（Time-Lapse / Hyperlapse）&quot;">​</a></h2><p>AI 在生成延时摄影时最容易出现画面高频闪烁（Flickering）或物体随机变异。最稳定的方式是强制锁定相机载具（三脚架锁定），并明确指定受时间加速影响的环境运动载体（如光影位移、流云）。</p><p>最稳触发词组：</p><ul><li><code>smooth intervalometer timelapse, locked-off tripod</code>（平滑间隔延时，杜绝机位抖动）</li><li><code>rapid sunlight trajectory and sweeping shadows</code>（用光影快速扫过强化延时真实感）</li><li><code>smooth motion-blur hyperlapse with fixed tracking anchor</code>（移动延时需加固定跟踪锚点）</li></ul><p>标准 Prompt 句式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A smooth locked-off tripod timelapse: stationary [Subject] remains rigid and unchanged at the center while dramatic golden hour sunlight and sharp shadows rapidly sweep across the scene, clean frame transition with no flickering.</span></span></code></pre></div><h2 id="_3-突然停格-变速定格-speed-ramp-time-freeze-bullet-time" tabindex="-1">3. 突然停格 / 变速定格（Speed Ramp / Time Freeze / Bullet Time） <a class="header-anchor" href="#_3-突然停格-变速定格-speed-ramp-time-freeze-bullet-time" aria-label="Permalink to &quot;3. 突然停格 / 变速定格（Speed Ramp / Time Freeze / Bullet Time）&quot;">​</a></h2><p>纯文字指令很难在单一镜头中精准控制「先动后停」。最稳定的触发方式是使用子弹时间（Bullet Time）或速度阶跃（Speed Ramp to Dead Freeze）——即主体物理动作瞬间归零，但摄像机维持微动环绕，这样模型不会误判为输出一张死图。</p><p>最稳触发词组：</p><ul><li><code>dynamic speed ramping into an instant dead freeze-frame</code>（动态变速瞬间锁死）</li><li><code>temporal freeze / time-freeze effect</code>（时间冻结效应）</li><li><code>bullet-time camera arc around frozen mid-air [Subject]</code>（围绕空中停格主体的子弹时间环绕）</li></ul><p>标准 Prompt 句式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dynamic action with sudden speed-ramping snapping into an absolute temporal freeze: the shattering [Subject] and floating debris freeze completely in mid-air, while the camera executes a smooth subtle orbital arc around the frozen moment.</span></span></code></pre></div><h2 id="触发词稳定性速查表" tabindex="-1">触发词稳定性速查表 <a class="header-anchor" href="#触发词稳定性速查表" aria-label="Permalink to &quot;触发词稳定性速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特效类型</th><th>最稳触发词（Core Tokens）</th><th>辅助约束词（防止翻车）</th></tr></thead><tbody><tr><td>千帧升格</td><td><code>Phantom Flex4K 1000fps</code>, <code>ultra slow-motion</code></td><td><code>suspended in mid-air</code>, <code>high-speed shutter</code></td></tr><tr><td>稳定延时</td><td><code>locked-off tripod timelapse</code>, <code>smooth intervalometer</code></td><td><code>no flickering</code>, <code>sweeping natural shadows</code></td></tr><tr><td>突然定格</td><td><code>speed-ramp to dead freeze</code>, <code>bullet-time temporal freeze</code></td><td><code>frozen mid-air debris</code>, <code>camera orbiting frozen subject</code></td></tr></tbody></table><hr><p>关联：升格触发词与 <a href="/tools/gemini-motion-layers">三层运动解耦</a> 的「全局时间速率统一」直接相关——那篇要求句首设 <code>In 1000fps ultra slow-motion</code>，本篇把它落到具体的高帧率机位写法。</p>',25)])])}const u=t(s,[["render",d]]);export{h as __pageData,u as default};
